insert into public.portfolio_projects (id,slug,status,featured,featured_order,sort_order,data) values ('0a254c07-1a7b-4853-abe5-d1bbcc2ee353','no-topo-do-campo-kmg-geek','draft',false,null,57,'{"title":"No topo do Campo","character":"","work":"Blue Lock","category":"MMV","date":"2025-04-21","summary":"","participation":"Sou Jorak, editor MMV e motion designer. Neste projeto, participei da edição de “No topo do Campo”, de KMG GEEK / Dino / Bloodz / Alvez / PeJota / As Ace / Kaji, com referências de Blue Lock. Minha contribuição conecta música, personagem e movimento na construção visual do lançamento. Acompanhe minha edição nesta página e explore os créditos e os links para conhecer o projeto completo.","process":"","techniques":[],"tools":[],"credits":"Edição: Killmer18, Shin Editor, Yuta_sz-Oficial, Z3CH1U, Halopeculiar,Jorak, Magrelão e Soul Music (New Kentoo e OZackEditor)","creditSource":"https://www.youtube.com/watch?v=C9ymH3ixZm4","coverUrl":"/media/covers/no-topo-do-campo-kmg-geek.jpg","coverSource":"youtube","coverAlt":"Thumbnail original de No topo do Campo","coverPosition":{"x":50,"y":50},"coverCredit":"Thumbnail do vídeo original no YouTube.","youtubeUrl":"https://www.youtube.com/watch?v=C9ymH3ixZm4","spotifyUrl":null,"xUrl":null,"processImages":[],"accent":"#32e6a1","verification":"Descrição completa contém crédito de edição para Jorak. Timestamps listam cantores; não representam intervalos individuais de editores.","coverSourceUrl":"https://www.youtube.com/watch?v=C9ymH3ixZm4","checkedAt":"2026-10-04","videoAvailability":"available"}'::jsonb);
