insert into public.portfolio_settings (id,data) values ('site','{"name":"Jorak","avatarUrl":"/media/jorak-avatar.jpg","headline":"Histórias que ganham movimento.","bio":"Editor MMV, motion designer e professor da Surfate Academy. Entre música, mangá e movimento, meu trabalho faz parte da cena geek brasileira.","career":"Atuo como editor MMV e motion designer em projetos da cena geek, com participações creditadas em trabalhos de AniRap, M4rkim, 7 Minutoz e outros artistas. Na Surfate Academy, ensino animação 2D no celular. Este portfólio reúne essas participações e os trechos que acompanham cada música.","email":"lvilaard@gmail.com","xUrl":"https://x.com/Jorakeditor","instagramUrl":"","linktreeUrl":"https://linktr.ee/Joraknv","whatsapp":"","showreelUrl":""}'::jsonb);
